{
  "name": "pdf-converter",
  "version": "1.0.0",
  "type": "module",
  "dependencies": {
    "pdfkit": "^0.15.0"
  }
}

const PDFDocument = require('pdfkit');
const fs = require('fs');

const inputPath = 'C:\\Users\\Administrator\\Desktop\\Claude_Code_完全学习手册.md';
const outputPath = 'C:\\Users\\Administrator\\Desktop\\Claude_Code_完全学习手册.pdf';

const content = fs.readFileSync(inputPath, 'utf8');

const doc = new PDFDocument({
  size: 'A4',
  margins: {
    top: 20 * 2.83465,
    bottom: 20 * 2.83465,
    left: 15 * 2.83465,
    right: 15 * 2.83465
  },
  info: {
    Title: 'Claude Code 完全学习手册',
    Author: 'Claude Code',
    Subject: 'Claude Code Learning Manual',
    Creator: 'Claude Code PDF Converter'
  }
});

const stream = fs.createWriteStream(outputPath);
doc.pipe(stream);

const fontSize = {
  title: 28,
  h1: 20,
  h2: 16,
  h3: 14,
  normal: 11,
  small: 9
};

const lineHeight = 1.4;
const pageWidth = doc.page.width - 30 * 2.83465;
let y = doc.page.margins.top;

// Simple markdown parser
const lines = content.split('\n');
let inCodeBlock = false;
let inTable = false;
let tableRows = [];
let listItems = [];

function wrapText(text, maxWidth, fontSize) {
  const words = text.split(' ');
  const lines = [];
  let currentLine = '';

  for (const word of words) {
    const testLine = currentLine ? `${currentLine} ${word}` : word;
    const width = doc.widthOfString(testLine, { fontSize });
    if (width > maxWidth && currentLine) {
      lines.push(currentLine);
      currentLine = word;
    } else {
      currentLine = testLine;
    }
  }
  if (currentLine) lines.push(currentLine);
  return lines;
}

function parseInlineMarkdown(text) {
  return text
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/\*(.+?)\*/g, '$1')
    .replace(/`(.+?)`/g, '$1')
    .replace(/#(\d+)/g, '')
    .trim();
}

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];

  // Code block
  if (line.startsWith('```')) {
    if (inCodeBlock) {
      doc.fontSize(9).font('Courier').text(tableRows.join('\n'), { continued: false });
      doc.moveDown(0.5);
      inCodeBlock = false;
    } else {
      inCodeBlock = true;
      tableRows = [];
    }
    continue;
  }

  if (inCodeBlock) {
    tableRows.push(line);
    continue;
  }

  // Headers
  if (line.startsWith('# ')) {
    doc.moveDown(0.8);
    doc.fontSize(fontSize.title).font('Helvetica-Bold');
    doc.text(parseInlineMarkdown(line.substring(2)), { align: 'center' });
    y = doc.y;
    doc.moveDown(0.5);
  } else if (line.startsWith('## ')) {
    doc.moveDown(0.6);
    doc.fontSize(fontSize.h1).font('Helvetica-Bold');
    doc.text(parseInlineMarkdown(line.substring(3)));
    y = doc.y;
    doc.moveDown(0.3);
  } else if (line.startsWith('### ')) {
    doc.moveDown(0.4);
    doc.fontSize(fontSize.h2).font('Helvetica-Bold');
    doc.text(parseInlineMarkdown(line.substring(4)));
    y = doc.y;
  } else if (line.startsWith('#### ')) {
    doc.moveDown(0.3);
    doc.fontSize(fontSize.h3).font('Helvetica-Bold');
    doc.text(parseInlineMarkdown(line.substring(5)));
    y = doc.y;
  }
  // Horizontal rule
  else if (line.match(/^---+$/)) {
    doc.moveDown(0.3);
    doc.moveTo(doc.page.margins.left, y).lineTo(doc.page.width - doc.page.margins.right, y).stroke();
    doc.moveDown(0.3);
  }
  // Table row
  else if (line.startsWith('|')) {
    const cells = line.split('|').filter(c => c.trim());
    tableRows.push(cells.map(c => c.trim()));
    inTable = true;
  }
  // End of table
  else if (inTable && !line.startsWith('|')) {
    // Draw table
    if (tableRows.length >= 2) {
      const headerRow = tableRows[0];
      const colWidths = headerRow.map(() => pageWidth / headerRow.length);

      // Header row
      doc.fontSize(fontSize.normal).font('Helvetica-Bold');
      let x = doc.page.margins.left;
      for (let c = 0; c < headerRow.length; c++) {
        doc.text(headerRow[c], x, y, { width: colWidths[c] - 10 });
        x += colWidths[c];
      }
      y = doc.y + 5;

      // Separator
      doc.moveTo(doc.page.margins.left, y).lineTo(doc.page.width - doc.page.margins.right, y).stroke();
      y += 5;

      // Data rows
      doc.font('Helvetica');
      for (let r = 1; r < tableRows.length; r++) {
        x = doc.page.margins.left;
        for (let c = 0; c < tableRows[r].length; c++) {
          doc.text(tableRows[r][c] || '', x, y, { width: colWidths[c] - 10 });
          x += colWidths[c];
        }
        y = doc.y + 3;
      }
    }
    inTable = false;
    tableRows = [];
    doc.moveDown(0.3);
  }
  // List items
  else if (line.match(/^[\*\-]\s/)) {
    doc.fontSize(fontSize.normal).font('Helvetica');
    const text = line.replace(/^[\*\-]\s/, '• ');
    const wrapped = wrapText(text, pageWidth, fontSize.normal);
    for (const l of wrapped) {
      doc.text(l, doc.page.margins.left, y, { width: pageWidth });
      y = doc.y;
    }
  }
  // Numbered list
  else if (line.match(/^\d+\.\s/)) {
    doc.fontSize(fontSize.normal).font('Helvetica');
    const text = line.replace(/^\d+\.\s/, '$1. ');
    const wrapped = wrapText(text, pageWidth, fontSize.normal);
    for (const l of wrapped) {
      doc.text(l, doc.page.margins.left, y, { width: pageWidth });
      y = doc.y;
    }
  }
  // Empty line
  else if (!line.trim()) {
    doc.moveDown(0.3);
  }
  // Regular paragraph
  else {
    doc.fontSize(fontSize.normal).font('Helvetica');
    const wrapped = wrapText(parseInlineMarkdown(line), pageWidth, fontSize.normal);
    for (const l of wrapped) {
      if (doc.y > doc.page.height - doc.page.margins.bottom - 50) {
        doc.addPage();
        y = doc.page.margins.top;
      }
      doc.text(l, doc.page.margins.left, y, { width: pageWidth });
      y = doc.y;
    }
  }

  // Check page break
  if (doc.y > doc.page.height - doc.page.margins.bottom - 50) {
    doc.addPage();
    y = doc.page.margins.top;
  }
}

doc.end();

stream.on('finish', () => {
  console.log('PDF created successfully:', outputPath);
});

stream.on('error', (err) => {
  console.error('Error:', err);
});

