    .replace(/\*(.+?)\*/g, '$1')
    .replace(/`(.+?)`/g, '$1')
    .replace(/#(\d+)/g, '')
    .trim();
}

function drawTable(rows, startY) {
  if (rows.length < 2) return startY;

  const colCount = Math.max(...rows.map(r => r.length));
  const colWidth = pageWidth / colCount;

