      if (y > doc.page.height - doc.page.margins.bottom - 50) {
        doc.addPage();
        y = doc.page.margins.top;
      }
      doc.text(l, doc.page.margins.left, y, { width: pageWidth });
      y = doc.y;
    }
  } else if (!line.trim()) {
    doc.moveDown(0.4);
  } else if (line.match(/^[\*\-]\s/)) {
    doc.fontSize(fontSize.normal).font('Helvetica').fillColor('black');
    const text = line.replace(/^[\*\-]\s/, '  • ');
    const wrapped = wrapText(parseInline(text), pageWidth, fontSize.normal);
    for (const l of wrapped) {
      if (y > doc.page.height - doc.page.margins.bottom - 50) {
        doc.addPage();
        y = doc.page.margins.top;
      }
      doc.text(l, doc.page.margins.left, y, { width: pageWidth });
      y = doc.y;
    }
  } else {
    doc.fontSize(fontSize.normal).font('Helvetica').fillColor('black');
    const wrapped = wrapText(parseInline(line), pageWidth, fontSize.normal);
    for (const l of wrapped) {
      if (y > doc.page.height - doc.page.margins.bottom - 50) {
        doc.addPage();
        y = doc.page.margins.top;
      }
      doc.text(l, doc.page.margins.left, y, { width: pageWidth });
      y = doc.y;
    }
  }

  if (y > doc.page.height - doc.page.margins.bottom - 50) {
    doc.addPage();
    y = doc.page.margins.top;
  }
}

doc.end();

stream.on('finish', () => {
  console.log('PDF created successfully:', outputPath);
});

stream.on('error', (err) => {
  console.error('Error:', err);
